"""원리 탭(1~6) HTML 생성기 → parts/t01.html … t06.html  (python3 gen_principle.py)"""
import os, json
B=os.path.dirname(os.path.abspath(__file__))

def poe(q,opts,ans,exp,ind='    '):
    return '%s<div class="poe" data-q="%s"\n%s     data-opts="%s"\n%s     data-ans="%d"\n%s     data-exp="%s"></div>'%(ind,q,ind,'||'.join(opts),ind,ans,ind,exp)

def tab(n, c):
    pre='t%d'%n
    o=[]
    o.append('<!-- ═══ TAB %d — %s ═══ -->'%(n,c['title']))
    o.append('<section class="panel" id="tab%d" role="tabpanel" aria-labelledby="tabbtn%d" tabindex="0">'%(n,n))
    o.append('  <div class="card">')
    o.append('    <div class="h3"><span class="badge b-mid">중등/흥미</span><span class="badge b-high">고등/수능</span><span class="badge b-poe">POE</span>%s</div>'%c['title'])
    o.append('    <div class="goal">🎯 %s</div>'%c['goal'])
    br='<span class="ar">→</span>'.join('<span class="st%s">%s</span>'%(' old' if i==0 else (' new' if i==len(c['bridge'])-1 else ''),b) for i,b in enumerate(c['bridge']))
    o.append('    <div class="organizer">\n      <div class="ot">%s</div>\n      %s\n      <div class="bridge">%s</div>\n    </div>'%(c['org_t'],c['org'],br))
    o.append(poe(*c['poe1']))
    o.append('    <div id="%s-misc"></div>\n  </div>\n'%pre)
    o.append('  <div class="card">')
    o.append('    <div class="h3">📖 %s <span class="badge b-mid">중등부터</span></div>'%c['fig_title'])
    o.append('    <div class="figwrap">\n      <svg class="fig" viewBox="0 0 780 %d" role="img" aria-label="%s">\n        {{FIG:%s}}\n      </svg>\n    </div>'%(c.get('fig_h',262),c['fig_aria'],c['fig']))
    o.append('    <div class="figcap">그림 %d-1. %s</div>'%(n,c['fig_cap']))
    o.append('    <div class="h4">🧰 이 단원의 도구 6가지와 역할</div>\n    <div class="parts">')
    for t,x in c['parts']: o.append('      <div class="part"><b>%s</b>%s</div>'%(t,x))
    o.append('    </div>')
    o.append('    <div class="h4">🧪 %s</div>\n    <div class="steps">'%c['lab_title'])
    for s in c['steps']: o.append('      <div class="step">%s</div>'%s)
    o.append('    </div>')
    o.append('    <div class="easy">\n      <div class="et">%s</div>\n      %s\n      <div class="compare">\n        <div class="cmp no"><b>❌ 이렇게 생각하기 쉬워요</b>%s</div>\n        <div class="cmp ok"><b>✅ 실제로는</b>%s</div>\n      </div>\n    </div>\n  </div>\n'%(c['easy_t'],c['easy'],c['no'],c['ok']))
    o.append('  <div class="grid2">\n    <div>\n      <div class="card">')
    o.append('        <div class="h3">🎛 %s</div>'%c['sim_title'])
    for (k,nm,mn,mx,st,val) in c['ctrls']:
        o.append('        <div class="ctrl">\n          <div class="ctrl-top"><span class="nm">%s</span><span class="vl" id="%s-%sV">—</span></div>\n          <input type="range" id="%s-%s" min="%s" max="%s" step="%s" value="%s" aria-label="%s">\n        </div>'%(nm,pre,k,pre,k,mn,mx,st,val,nm))
    if c.get('extra_row'): o.append('        '+c['extra_row'])
    o.append('        <div class="kv">')
    for (k,nm,cl) in c['kv']: o.append('          <div class="cell %s"><span class="k">%s</span><span class="v" id="%s-%s">—</span></div>'%(cl,nm,pre,k))
    o.append('        </div>\n        <p class="tiny">%s</p>\n      </div>'%c['note'])
    o.append(poe(*c['poe2'],ind='      '))
    o.append('      <div class="hintbox" data-hints="%s"></div>\n    </div>'%c['hints'])
    o.append('    <div>\n      <div class="card tight">\n        <div class="cv-wrap">\n          <div class="cv-tools"><button type="button" class="btn sm fsb" data-fsx="%s" title="전체화면으로 보기 (수업용)">⛶ 전체화면</button><button type="button" class="btn sm" data-png="%s-cv" data-pngname="%s">🖼 PNG</button></div>\n          <canvas id="%s-cv" role="img" aria-label="%s" style="height:%dpx"></canvas>\n          <div class="cv-cap">%s</div>\n        </div>\n        <div id="%s-time"></div>\n        <div class="cv-wrap" style="margin-top:9px">\n          <canvas id="%s-cv2" role="img" aria-label="%s" style="height:%dpx"></canvas>\n          <div class="cv-cap">%s</div>\n        </div>\n      </div>'%(pre,pre,c['png'],pre,c['cv1_aria'],c.get('cv1_h',340),c['cv1_cap'],pre,pre,c['cv2_aria'],c.get('cv2_h',330),c['cv2_cap']))
    o.append('      <div class="card lv-high">\n        <div class="h4">📐 식으로 정리하기 <span class="badge b-high">고등</span></div>\n        %s\n      </div>\n    </div>\n  </div>'%c['formulas'])
    if c.get('extra'): o.append(c['extra'])
    o.append('</section>\n')
    return '\n'.join(o)

